package gg.eternal.core.state;
import java.util.ArrayDeque;
public final class InputState { private static final boolean[] KEYS=new boolean[512]; private static final ArrayDeque<Long> LEFT=new ArrayDeque<>(),RIGHT=new ArrayDeque<>(); public static void key(int k,boolean d){if(k>=0&&k<KEYS.length)KEYS[k]=d;} public static boolean keyDown(int k){return k>=0&&k<KEYS.length&&KEYS[k];} public static void mouse(int b,boolean d){if(!d)return;long n=System.currentTimeMillis();if(b==0)LEFT.add(n);if(b==1)RIGHT.add(n);trim(LEFT,n);trim(RIGHT,n);} private static void trim(ArrayDeque<Long> q,long n){while(!q.isEmpty()&&n-q.peek()>1000)q.poll();} public static int leftCps(){trim(LEFT,System.currentTimeMillis());return LEFT.size();} public static int rightCps(){trim(RIGHT,System.currentTimeMillis());return RIGHT.size();} }
